package main

import (
	"fmt"
	"os"
	"sync"
)

func main() {
	var mu sync.Mutex
	mu.Lock()
	defer mu.Unlock() // 函数结束时解锁

	f, err := os.Create("demo.txt")
	if err != nil {
		fmt.Println("创建文件失败:", err)
		return
	}
	defer f.Close() // 函数结束时关闭文件

	fmt.Fprintln(f, "hello")
	fmt.Println("写入中")
}

