package main

import "fmt"

// 可变参数 + 命名返回值 + 裸 return
func average(nums ...float64) (avg float64, err error) {
	if len(nums) == 0 {
		return 0, fmt.Errorf("没有数据")
	}
	for _, n := range nums {
		avg += n
	}
	avg /= float64(len(nums))
	return
}

// 递归
func fact(n int) int {
	if n <= 1 {
		return 1
	}
	return n * fact(n-1)
}

func main() {
	// 立即执行函数
	func() {
		fmt.Println("=== 开始 ===")
	}()

	// 多返回值 + 命名返回值
	avg, err := average(1, 2, 3, 4)
	if err != nil {
		fmt.Println("出错:", err)
		return
	}
	fmt.Println("平均值:", avg)

	// 切片展开
	xs := []float64{5, 6}
	avg2, _ := average(xs...)
	fmt.Println("平均值2:", avg2)

	// 匿名函数 + 函数作为值
	double := func(x float64) float64 { return x * 2 }
	fmt.Println("两倍:", double(avg))

	// 闭包捕获外部变量
	count := 0
	increment := func() { count++ }
	increment()
	increment()
	fmt.Println("计数:", count)

	// defer 与 recover
	safe := func(f func()) {
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("已捕获:", r)
			}
		}()
		f()
	}
	safe(func() { panic("出错了") })

	// defer 的执行顺序是后进先出，参数在 defer 时就求值
	for i := 1; i <= 3; i++ {
		defer fmt.Println("defer", i)
	}
	fmt.Println("阶乘:", fact(5))
}
